  const WX_ICON={calm:"☀️",flow:"🌀",abyss:"🌊",moon:"🌙",storm:"⛈️",bloom:"🪸",aurora:"✨",mist:"🏛️"};
  const RESIDENTS=[
    {k:"turtle",n:"海龟教授",icon:"🐢",at:0,role:"复习分析与错因报告"},
    {k:"octopus",n:"章鱼老板",icon:"🐙",at:0,role:"种子与增益商店"},
    {k:"hermit",n:"寄居蟹工匠",icon:"🦀",at:5,role:"地图装饰与扩建"},
    {k:"keeper",n:"灯塔管理员",icon:"🗼",at:3,role:"连续学习与海况预报"},
    {k:"seahorse",n:"海马巡逻员",icon:"🐠",at:12,role:"听力与声呐记录"},
    {k:"jelly",n:"水母歌手",icon:"🪼",at:20,role:"句子节奏与跟读"}
  ];
  const RES_INDEX={turtle:0,octopus:1,hermit:2,keeper:3,seahorse:4,jelly:5};
  const REL_LEVELS=[0,12,35,75,140];
  const RELICS=["问候贝片","餐厅铜牌","方向罗盘","购物清单","工作印章","旅行船票","健康药瓶","电话听筒","紧急浮标","日常相册"];
  // 当前句库共300句。十件遗物必须在现有内容量内都能真正获得；
