  function renderCodex(cat){modal.classList.remove("boss-v5-open");setView(cat);title.textContent="潮汐博物馆 · 六类独立展厅";sync(true);const defs=codexDefs(),got=S.eco.codex[cat],arrival=S.eco.arrival;body.innerHTML='<div class="eco-statbar"><div class="eco-stat"><small>扩展收藏</small><b>'+collected()+' / 52</b></div><div class="eco-stat"><small>鱼类馆</small><b>'+Object.keys(S.eco.codex.fish).length+' / 12</b></div><div class="eco-stat"><small>植物馆</small><b>'+Object.keys(S.eco.codex.plants).length+' / 12</b></div><div class="eco-stat"><small>生态等级</small><b>Lv.'+(S.eco.world.statueLevel+1)+'</b></div></div>'+codexTabs(cat)+'<div class="eco-detail" id="ecoCodexDetail"></div><div class="eco-grid">'+defs[cat].map(x=>{const o=got[x[0]],lock=!o,isNew=arrival&&arrival.cat===cat&&arrival.key===x[0];return '<article class="eco-card eco-entry '+(lock?'locked ':'')+(isNew?'eco-arrival ':'')+'" data-entry="'+x[0]+'">'+mediaFor(cat,x[0],lock?'❔':x[2])+'<h3>'+(lock?'未发现':x[1])+'</h3><p>'+(lock?clue(cat,x[0]):'首次发现 '+o.first)+'</p><span class="eco-tag">'+(lock?'线索未知':'已观察 '+o.seen+' 次')+'</span></article>';}).join("")+'</div>';body.querySelectorAll("[data-codex]").forEach(b=>b.onclick=()=>renderCodex(b.getAttribute("data-codex")));body.querySelectorAll("[data-entry]").forEach(b=>{const it=defs[cat].find(x=>x[0]===b.getAttribute("data-entry"));b.onclick=()=>showCodexDetail(cat,it);});showCodexDetail(cat,defs[cat][0]);if(arrival&&arrival.cat===cat){setTimeout(()=>{if(S.eco.arrival===arrival){S.eco.arrival=null;save();}},1400);}}

