  function renderSettings(){title.textContent="生态设置与进度保护";const on=!!S.eco.lowMotion,bk=!!LS.getItem(SAVE+"_before_v3"),lc=S.eco.lastLayoutCheck;body.innerHTML='<div class="eco-control"><b>背景音乐</b><input id="ecoBgm" type="range" min="0" max="1" step="0.05" value="'+(S.bgm||0)+'"><span id="ecoBgmV">'+Math.round((S.bgm||0)*100)+'%</span></div><div class="eco-control"><b>音效音量</b><input id="ecoSfx" type="range" min="0" max="1" step="0.05" value="'+(S.sfx||0)+'"><span id="ecoSfxV">'+Math.round((S.sfx||0)*100)+'%</span></div><div class="eco-control"><b>TTS语速</b><input id="ecoRate" type="range" min="0.5" max="1.2" step="0.05" value="'+(S.rate||.68)+'"><span id="ecoRateV">'+(S.rate||.68).toFixed(2)+'</span></div><div class="eco-control"><b>画质档位</b><div class="eco-quality">'+[["high","高"],["balanced","均衡"],["low","省电"]].map(x=>'<button data-quality="'+x[0]+'" class="'+((S.eco.quality||"high")===x[0]?'on':'')+'">'+x[1]+'</button>').join("")+'</div><span></span></div><div class="eco-grid">'+shell("减少动态效果",on?'✅':'🌊',false,on?'已减少鱼群、气泡和远景动画':'保留完整海底动画',[on?'已开启':'未开启'])+shell("记忆排程保护","🛡️",false,"天气、任务、居民和收藏不能修改到期时间",["永久开启"])+shell("离线模式","📴",false,"所有生态数据和图片均保存在本机",["无需联网"])+'</div><div class="eco-restore-info">升级前备份：'+(bk?'已找到，可一键恢复':'尚未找到')+'。恢复前会先保存当前V3进度到 <b>'+SAVE+'_before_restore_v31</b>。<br>设备布局：'+(lc?((lc.ok?'通过':'需检查')+' · '+lc.width+'px · '+(lc.safari?'Safari':'其他浏览器')):'尚未在当前设备运行')+'</div><div class="eco-actions"><button id="ecoMotion">'+(on?'恢复完整动画':'减少动态效果')+'</button><button id="ecoLayoutTest">运行当前设备布局自检</button><button id="ecoExport">导出进度</button><button id="ecoImport">导入进度</button><button id="ecoRestore" class="eco-danger" '+(bk?'':'disabled')+'>恢复升级前进度</button></div>';
    const ranges=[["ecoBgm","bgm","ecoBgmV",v=>Math.round(v*100)+"%"],["ecoSfx","sfx","ecoSfxV",v=>Math.round(v*100)+"%"],["ecoRate","rate","ecoRateV",v=>v.toFixed(2)]];ranges.forEach(a=>{const e=document.getElementById(a[0]);e.oninput=()=>{const v=+e.value;S[a[1]]=v;document.getElementById(a[2]).textContent=a[3](v);};e.onchange=()=>{save();if(a[1]==="bgm"){try{stopBgm();if(mode==="play"&&S.bgm)startBgm();}catch(e){}}};});
    body.querySelectorAll("[data-quality]").forEach(b=>b.onclick=()=>setQuality(b.getAttribute("data-quality")));document.getElementById("ecoMotion").onclick=()=>{S.eco.lowMotion=!S.eco.lowMotion;applyQuality();save();renderSettings();};document.getElementById("ecoLayoutTest").onclick=layoutSelfTest;document.getElementById("ecoExport").onclick=()=>{const b=document.getElementById("btnExport");if(b){close();b.click();}};document.getElementById("ecoImport").onclick=()=>{const b=document.getElementById("btnImportSave");if(b){close();b.click();}};document.getElementById("ecoRestore").onclick=restoreBackup;
  }

