  document.getElementById("ecoClose").onclick=close;modal.onclick=e=>{if(e.target===modal)close();};document.addEventListener("keydown",e=>{if(e.key==="Escape"&&modal.classList.contains("on"))close();});
  [["farmTask","tasks"],["farmCodex","codex"],["farmAchievement","ach"],["farmResidents","residents"],["farmSettings","settings"]].forEach(x=>{const b=document.getElementById(x[0]);if(b)b.onclick=()=>open(x[1]);});
  const wxBar=document.getElementById("wxBar");if(wxBar){wxBar.style.cursor="pointer";wxBar.title="打开今日海况与明日预报";wxBar.onclick=()=>open("weather");}
  if(all)all.onclick=function(){const ripe=[];S.farm.plots.forEach((p,i)=>{if(p&&CROPS[p.crop]&&p.nut>=CROPS[p.crop].need)ripe.push(i);});if(!ripe.length){toast("还没有成熟作物，完成复习就能获得养分");return;}ripe.forEach((i,n)=>setTimeout(()=>{const p=S.farm.plots[i];if(p&&CROPS[p.crop])harvest(i,Math.round(CROPS[p.crop].yield*curWeather().coin));},n*860));};
  const oldHarvest=harvest;harvest=function(i,pay){const p=S.farm.plots[i],crop=p&&p.crop,a=crop&&ATTRACT[crop];oldHarvest(i,pay);if(crop){found("plants",crop,CROPS[crop].n,false);if(a)found("fish",a.k,a.n,false);emit("harvest",{id:"harvest:"+Date.now()+":"+i,crop});save();}};
  // 主动退出只显示本轮结算，不能伪装成“完成一轮”来刷任务和居民好感。
  let sentAbortPending=false,wordAbortPending=false;
  const quitSentence=document.getElementById("qQuit");
  if(quitSentence&&quitSentence.onclick){const oldQuit=quitSentence.onclick;quitSentence.onclick=function(e){sentAbortPending=true;const r=oldQuit.call(this,e);toast("本轮提前结束，不计任务与居民好感");return r;};}
  ["btnSent","btnSent2","btnSentAgain"].forEach(id=>{const b=document.getElementById(id);if(b&&b.addEventListener)b.addEventListener("click",()=>{sentAbortPending=false;});});
  ["btnPlay","btnPlay2","btnAgain","btnFarmPlay"].forEach(id=>{const b=document.getElementById(id);if(b&&b.addEventListener)b.addEventListener("click",()=>{wordAbortPending=false;});});
  if(window.addEventListener)window.addEventListener("keydown",e=>{if(e.key==="Escape"&&mode==="play")wordAbortPending=true;},true);
  const oldShowScreen=showScreen;showScreen=function(id){
    oldShowScreen(id);
    if(id==="scResult"){
      if(wordAbortPending){wordAbortPending=false;toast("主动撤离不计单词轮次与居民好感");return;}
      emit("word_session",{id:"word:"+Date.now(),ok:keyOk|0,bad:keyBad|0,dueCleared:dueCount()===0});
    }else if(id==="scSentResult"){
      let st={Q:[],qi:0,nOk:0,nBad:0};try{st=SENT._st();}catch(e){}
      const complete=!sentAbortPending&&Array.isArray(st.Q)&&st.Q.length>0&&st.qi>=st.Q.length;
      sentAbortPending=false;
      if(!complete){toast("未完成整轮，不计句子任务与居民好感");return;}
      emit("sentence_session",{id:"sent:"+Date.now(),ok:st.nOk|0,bad:st.nBad|0});
    }
  };
  const oldRefresh=refreshFarm;refreshFarm=function(){ensure();sync(true);oldRefresh();const m=mastered(),lv=Math.max(1,Math.floor(m/100)+1),pct=m%100,t=document.getElementById("farmLevelText"),bar=document.getElementById("farmLevelBar");if(t)t.textContent="Lv."+lv+" · "+m+"词";if(bar)bar.style.width=pct+"%";const ready=S.farm.plots.some(p=>p&&CROPS[p.crop]&&p.nut>=CROPS[p.crop].need);if(all)all.classList.toggle("ready",ready);const dock=document.getElementById("farmBuffDock");if(dock)dock.innerHTML=BOOST_KEYS.map(k=>'<span title="'+esc(BOOSTS[k].n)+' ×'+(S.farm.boosts[k]|0)+'" style="opacity:'+((S.farm.boosts[k]|0)?1:.45)+'">'+({slow:"🌀",reef:"🛡️",echo:"🎯",buoy:"🛟",deep:"🌊"}[k])+'<small>'+(S.farm.boosts[k]|0)+'</small></span>').join("");save();};
  document.addEventListener("visibilitychange",()=>{if(!bossRun)return;if(document.hidden){bossHiddenAt=Date.now();if(bossTimer){clearInterval(bossTimer);bossTimer=null;}if(bossFxFrame){cancelAnimationFrame(bossFxFrame);bossFxFrame=0;}}else if(bossHiddenAt){if(bossRun.deadline)bossRun.deadline+=Date.now()-bossHiddenAt;bossHiddenAt=0;bossFxStart();startBossClock(true);}});
  function openBosses(){open("codex");renderCodex("bosses");}
  function bossHomeStatus(){
    const seen=bossCandidateRecords().length,due=dueCount(),cleared=BOSSES.filter((_,i)=>!!S.eco.bossesCleared["b"+i]).length,unlocked=BOSSES.filter((_,i)=>bossUnlocked(i)).length;
    if(!seen)return {state:"learn",text:"先完成至少1个单词，再开始首战",button:"进入Boss大厅"};
    if(due>0)return {state:"due",text:"可以直接练习开战 · "+due+" 个到期词将优先出现",button:"查看Boss与解锁条件"};
    return {state:"ready",text:unlocked+"场已开放 · 已击退 "+cleared+"/4",button:unlocked?"进入Boss大厅":"查看解锁条件"};
  }
